// TestScanInline pins the EXISTING scan kickoff contract the admin collections
// table renders inline (web-ui-phase-3 group 6): POST /api/v1/libraries/{id}/scan
// → 200 with {library_id, discovered, persisted} and warnings OMITTED from the
// wire when the scan produced none (omitempty — the client renders no warnings
// list for an absent key); a scan failure is 500 internal_error with the
// canonical body (the row surfaces it inline); a non-integer id is 400
// bad_request with deps.Scan never called. The inline-on-the-scanned-row-only
// behavior is client-side (web Collections.test.tsx) — this test owns the
// wire contract. Additive: pins handlers.go scanLibrary as-is.
func TestScanInline(t *testing.T) {
	st := openAPIStore(t)

	cases := []struct {
		name           string
		id             string
		scanResult     scan.Result
		scanErr        error
		wantStatus     int
		wantErrCode    string // "" = expect a 200 scanResponse body
		wantScanCalled bool
		wantScanID     int64 // overrides the Result-derived id for error-path cases
	}{
		{
			name:           "result_without_warnings_omits_the_key",
			id:             "11",
			scanResult:     scan.Result{LibraryID: 11, Discovered: 3, Persisted: 3},
			wantStatus:     http.StatusOK,
			wantScanCalled: true,
		},
		{
			name:           "result_with_warnings_carries_them_verbatim",
			id:             "12",
			scanResult:     scan.Result{LibraryID: 12, Discovered: 5, Persisted: 4, Warnings: []string{"skipped one unreadable file", "two paths ignored"}},
			wantStatus:     http.StatusOK,
			wantScanCalled: true,
		},
		{
			name:           "scan_failure_is_500_internal_error",
			id:             "13",
			scanErr:        context.DeadlineExceeded,
			wantStatus:     http.StatusInternalServerError,
			wantErrCode:    "internal_error",
			wantScanCalled: true,
			wantScanID:     13, // the stub returns a zero Result; assert the parsed id directly
		},
		{
			name:        "non_integer_id_is_400_bad_request",
			id:          "abc",
			wantStatus:  http.StatusBadRequest,
			wantErrCode: "bad_request",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var scanIDs []int64
			scanStub := func(_ context.Context, libraryID int64) (scan.Result, error) {
				scanIDs = append(scanIDs, libraryID)
				return tc.scanResult, tc.scanErr
			}
			h := New(Deps{AdminToken: adminToken, Store: st, Scan: scanStub})

			resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries/"+tc.id+"/scan", "", adminToken)
			defer resp.Body.Close()
			raw, err := io.ReadAll(resp.Body)
			if err != nil {
				t.Fatalf("read body: %v", err)
			}
			if resp.StatusCode != tc.wantStatus {
				t.Fatalf("status = %d, want %d (body %s)", resp.StatusCode, tc.wantStatus, raw)
			}

			if tc.wantErrCode != "" {
				// The body was drained into raw above, so decode the canonical
				// error from there (decodeError would see EOF).
				var eb errorBody
				if err := json.Unmarshal(raw, &eb); err != nil {
					t.Fatalf("decode error body from %s: %v", raw, err)
				}
				if eb.Error.Code != tc.wantErrCode {
					t.Fatalf("error code = %q, want %q", eb.Error.Code, tc.wantErrCode)
				}
			}

			// deps.Scan was called exactly once with the parsed id — except
			// for a non-integer id, which never reaches the domain.
			if !tc.wantScanCalled {
				if len(scanIDs) != 0 {
					t.Fatalf("scan kicked off for id %q: %v", tc.id, scanIDs)
				}
				return
			}
			wantID := tc.scanResult.LibraryID
			if tc.wantScanID != 0 {
				wantID = tc.wantScanID
			}
			if len(scanIDs) != 1 || scanIDs[0] != wantID {
				t.Fatalf("scan calls = %v, want exactly [%d]", scanIDs, wantID)
			}

			var sr scanResponse
			if err := json.Unmarshal(raw, &sr); err != nil {
				t.Fatalf("decode scanResponse from %s: %v", raw, err)
			}
			if sr.LibraryID != tc.scanResult.LibraryID ||
				sr.Discovered != tc.scanResult.Discovered ||
				sr.Persisted != tc.scanResult.Persisted {
				t.Fatalf("scanResponse = %+v, want the stubbed scan.Result %+v", sr, tc.scanResult)
			}

			if len(tc.scanResult.Warnings) == 0 {
				// omitempty: an empty warning set must NOT put the key on the
				// wire at all.
				if strings.Contains(string(raw), "\"warnings\"") {
					t.Fatalf("empty warnings leaked onto the wire: %s", raw)
				}
			} else {
				// Warnings travel verbatim, in order.
				var wire []string
				if err := json.Unmarshal(raw, &struct {
					Warnings *[]string `json:"warnings"`
				}{&wire}); err != nil {
					t.Fatalf("decode warnings from %s: %v", raw, err)
				}
				if len(wire) != len(tc.scanResult.Warnings) {
					t.Fatalf("wire warnings = %v, want %v", wire, tc.scanResult.Warnings)
				}
				for i, w := range tc.scanResult.Warnings {
					if wire[i] != w {
						t.Fatalf("wire warnings[%d] = %q, want %q", i, wire[i], w)
					}
				}
			}
		})
	}
}
